type MessageTree = Record<string, unknown>

const applyFlat = (target: MessageTree, values: Record<string, string>): MessageTree => {
  for (const [path, value] of Object.entries(values)) {
    const parts = path.split('.')
    const key = parts.pop()!
    const parent = parts.reduce<MessageTree>((node, part) => {
      const existing = node[part]
      if (!existing || typeof existing !== 'object' || Array.isArray(existing)) node[part] = {}
      return node[part] as MessageTree
    }, target)
    parent[key] = value
  }
  return target
}

const deepMerge = (base: MessageTree, patch: MessageTree): MessageTree => Object.fromEntries(
  Object.entries(base).map(([key, value]) => [
    key,
    value && typeof value === 'object' && !Array.isArray(value)
      ? deepMerge(value as MessageTree, (patch?.[key] ?? {}) as MessageTree)
      : patch?.[key] ?? value,
  ]),
)

const zhCN = applyFlat(deepMerge(enUS, overrides), explicitBusinessTranslations) as typeof enUS
export default zhCN
export { zhCN }
